# Intermediate unit 25 – Cause and effect. Bám sách: trang 54–55 (đã xem ảnh trang) + đáp án + Mini dictionary. Không chép nguyên văn.
# bring back (gợi nhớ – u1) đã có thẻ → chỉ nhắc.
theory = (
 H("A", "Verbs with off", "Các động từ với off")
 + P("Several cause-and-effect phrasal verbs use <i>off</i>. Terrorists <b>set off</b> a bomb in the rush hour (cause an explosion); someone accidentally <b>sets off</b> a burglar alarm (makes it ring). A scandal <b>sets off</b> a series of events ending in a general election (causes them, often unintentionally). Mentioning flying saucers <b>sets</b> someone <b>off</b> talking for hours; the end of a play <b>sets</b> a woman <b>off</b> laughing or crying. A crisis <b>sparks off</b> a civil war (makes it suddenly happen); a speech <b>triggers off</b> violent protests (makes a difficult situation suddenly begin).",
     "Nhiều phrasal verb chỉ nguyên nhân – kết quả dùng <i>off</i>. Kẻ khủng bố <b>set off</b> quả bom giờ cao điểm (gây nổ); ai đó vô tình <b>sets off</b> chuông báo trộm (làm chuông kêu). Một vụ bê bối <b>sets off</b> chuỗi sự kiện dẫn tới tổng tuyển cử (gây ra, thường không cố ý). Nhắc tới đĩa bay là <b>sets</b> anh ta <b>off</b> nói hàng giờ; đoạn kết vở kịch <b>sets</b> cô ấy <b>off</b> cười hay khóc. Khủng hoảng <b>sparks off</b> nội chiến (khiến bùng nổ đột ngột); bài phát biểu <b>triggers off</b> các cuộc biểu tình bạo lực (châm ngòi tình huống khó khăn).")
 + H("B", "Other cause and effect verbs", "Các động từ nguyên nhân – kết quả khác")
 + T([
   ("bring about sth", "make something happen – a new airport and changes on an island", "gây ra, mang lại – sân bay mới và các thay đổi trên đảo"),
   ("lie behind sth", "be the real reason for something – Mr Wild’s attack", "là lý do thực sự – vụ ông Wild công kích"),
   ("pay sb back", "do something unpleasant to someone who did something unpleasant to you", "trả đũa ai"),
   ("stir up sth", "cause arguments or bad feeling, usually on purpose", "khuấy động, gây xích mích (thường cố ý)"),
   ("bring back sth", "make you remember the past – a photo of Scotland (card in Unit 1)", "gợi nhớ – tấm ảnh ở Scotland (đã có thẻ ở bài 1)"),
   ("rule out sth", "decide something is impossible – doctors and cancer", "loại trừ khả năng – bác sĩ và bệnh ung thư"),
   ("spring from sth", "be caused by – teenagers’ problems and insecurity", "bắt nguồn từ – vấn đề tuổi teen và sự bất an"),
 ])
)
